import{_ as a,o,c as i,a0 as t}from"./chunks/framework.Bud-GSzw.js";const m=JSON.parse('{"title":"CHANGELOG","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"en/changelog.md","filePath":"en/changelog.md"}'),n={name:"en/changelog.md"};function d(l,e,r,c,s,h){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">CHANGELOG <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;CHANGELOG&quot;">​</a></h1><h2 id="_1-1-5-2026-09-26" tabindex="-1">[1.1.5] - 2026-09-26 <a class="header-anchor" href="#_1-1-5-2026-09-26" aria-label="Permalink to &quot;[1.1.5] - 2026-09-26&quot;">​</a></h2><h3 id="🚀-performance" tabindex="-1">🚀 Performance <a class="header-anchor" href="#🚀-performance" aria-label="Permalink to &quot;🚀 Performance&quot;">​</a></h3><ul><li>Prepare field-specific decoders and the update validation route at registration. In a local paired conversion benchmark on 20,000 rows with scalar, datetime, and list fields, median time fell from 0.194 to 0.166 seconds.</li><li>Cached type inspection while decoding rows. In a local 10,000-row benchmark, median query time fell from 0.098 to 0.068 seconds (sync) and from 0.108 to 0.074 seconds (async).</li><li>Bound <code>LIMIT</code> and <code>OFFSET</code> as SQL parameters. In a local 1,000-query pagination benchmark, median time fell from 0.0341 to 0.0315 seconds.</li><li>Removed unused JSON conversion in <code>__in</code> filters. Building 500 filters of 1,000 integers fell from 0.138 to 0.091 seconds locally.</li></ul><h3 id="🐞-fixed" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Updated documentation dependencies to address known vulnerabilities and limited the optional <code>cryptography</code> dependency to a fixed release on Python 3.10+.</li><li>Protected in-flight SQLite calls after async cancellation and rolled back open transactions; sync transactions also roll back on interruptions.</li><li><code>update()</code> now validates changed values, with affected-row validation for models that have custom validators or configuration.</li><li><code>register()</code> now raises <code>SchemaMismatchError</code> when an existing table&#39;s columns, types, primary key, nullability, or FTS searchable columns differ from the model.</li><li>Adding full-text search to an existing table now indexes existing rows immediately.</li></ul><h3 id="📚-docs" tabindex="-1">📚 Docs <a class="header-anchor" href="#📚-docs" aria-label="Permalink to &quot;📚 Docs&quot;">​</a></h3><ul><li>Corrected the error and exception guides, backup example, projection advice, batched async reads, and continuation-based pagination.</li></ul><h3 id="⚠️-compatibility" tabindex="-1">⚠️ Compatibility <a class="header-anchor" href="#⚠️-compatibility" aria-label="Permalink to &quot;⚠️ Compatibility&quot;">​</a></h3><ul><li>On Python 3.9, the <code>encryption</code>, <code>all</code>, and <code>dev</code> extras no longer install <code>cryptography</code>. Core Python 3.9 support remains.</li><li>Invalid partial updates now raise Pydantic <code>ValidationError</code>. Incompatible existing tables raise <code>SchemaMismatchError</code> on registration; migrate them explicitly.</li></ul><hr><h2 id="_1-1-4-2026-06-22" tabindex="-1">[1.1.4] - 2026-06-22 <a class="header-anchor" href="#_1-1-4-2026-06-22" aria-label="Permalink to &quot;[1.1.4] - 2026-06-22&quot;">​</a></h2><h3 id="🐞-fixed-1" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed-1" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Validated all generated SQLite identifiers and rejected unknown composite-index fields before constructing schema SQL.</li><li>Hardened string filters so unsupported raw SQL fragments now raise <code>QueryValidationError</code> instead of being passed through to SQL.</li><li>Aligned async query validation with the sync implementation, including unknown-field checks and model-aware filter value serialization.</li><li>Fixed async filtering for <code>date</code>, <code>datetime</code>, <code>list</code>, and <code>dict</code> values.</li><li>Fixed <code>__in</code> handling so normal lists/tuples/sets work consistently and empty collections return no rows.</li><li>Fixed offset-only pagination by emitting SQLite&#39;s required unlimited <code>LIMIT</code> clause.</li><li>Tightened <code>limit</code> / <code>offset</code> validation to reject negative values, floats, booleans, and strings.</li><li>Added a clear <code>TypeError</code> when <code>insert_many()</code> receives mixed model types.</li><li>Serialized reads and connection shutdown with the existing locks so <code>close()</code> cannot race active queries.</li><li>Protected <code>vacuum()</code> and async <code>execute_raw()</code> with the existing connection locks.</li></ul><h3 id="🧪-tests" tabindex="-1">🧪 Tests <a class="header-anchor" href="#🧪-tests" aria-label="Permalink to &quot;🧪 Tests&quot;">​</a></h3><ul><li>Added regression tests for unsafe string filters, async field validation, serialized filter values, <code>__in</code>, offset-only pagination, strict pagination types, and mixed-model bulk inserts.</li></ul><h3 id="📚-docs-1" tabindex="-1">📚 Docs <a class="header-anchor" href="#📚-docs-1" aria-label="Permalink to &quot;📚 Docs&quot;">​</a></h3><ul><li>Added an APSW full-access implementation plan.</li></ul><h3 id="⚠️-compatibility-1" tabindex="-1">⚠️ Compatibility <a class="header-anchor" href="#⚠️-compatibility-1" aria-label="Permalink to &quot;⚠️ Compatibility&quot;">​</a></h3><ul><li>String filters now support only simple comparisons such as <code>&quot;age &gt; 10&quot;</code> or <code>&quot;name = &#39;Alice&#39;&quot;</code>. Use keyword filters such as <code>age__gte=10</code> for advanced filtering.</li><li>Python 3.9 remains supported for the core package. Some optional and development dependencies cannot provide their latest security-fixed wheels on Python 3.9; use Python 3.10+ for the <code>speed</code>, <code>encryption</code>, and <code>dev</code> extras when processing untrusted input.</li></ul><hr><h2 id="_1-1-1-2026-05-16" tabindex="-1">[1.1.1] - 2026-05-16 <a class="header-anchor" href="#_1-1-1-2026-05-16" aria-label="Permalink to &quot;[1.1.1] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-added" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Explicit Transactions</strong>: Added <code>atomic()</code> context manager to <code>NyanSQLite</code> and <code>async with atomic()</code> to <code>NyanSQLiteAIO</code> for manual transaction control.</li><li><strong>Nested Transactions</strong>: Added support for nested <code>atomic()</code> blocks.</li></ul><h3 id="🔄-changed" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li><strong>Thread Safety</strong>: Improved thread safety by switching to <code>threading.RLock</code> in <code>NyanSQLite</code>.</li><li><strong>Async Safety</strong>: Implemented re-entrant async lock in <code>NyanSQLiteAIO</code> to prevent deadlocks when using <code>atomic()</code>.</li></ul><hr><h2 id="_1-1-0-2026-05-16" tabindex="-1">[1.1.0] - 2026-05-16 <a class="header-anchor" href="#_1-1-0-2026-05-16" aria-label="Permalink to &quot;[1.1.0] - 2026-05-16&quot;">​</a></h2><h3 id="🚀-added-1" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added-1" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Asynchronous Support</strong>: Full support for <code>asyncio</code> via <code>NyanSQLiteAIO</code> class.</li><li><strong>Improved Performance</strong>: Optimized read operations by minimizing thread context switching and processing rows efficiently in <code>asyncio.to_thread</code>.</li><li><strong>Documentation Updates</strong>: Added English and Japanese documentation for asynchronous usage.</li></ul><h3 id="🔄-changed-1" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed-1" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li>Internal optimization for <code>query</code>, <code>select</code>, and <code>search</code> methods in <code>NyanSQLiteAIO</code>.</li><li>Optimized read operations in synchronous <code>NyanSQLite</code> class by minimizing lock duration.</li></ul><hr><h2 id="_1-0-1-2026-05-15" tabindex="-1">[1.0.1] - 2026-05-15 <a class="header-anchor" href="#_1-0-1-2026-05-15" aria-label="Permalink to &quot;[1.0.1] - 2026-05-15&quot;">​</a></h2><h3 id="🐞-fixed-2" tabindex="-1">🐞 Fixed <a class="header-anchor" href="#🐞-fixed-2" aria-label="Permalink to &quot;🐞 Fixed&quot;">​</a></h3><ul><li>Minor bug fixes and performance improvements.</li></ul><hr><h2 id="_1-0-0-2026-05-15" tabindex="-1">[1.0.0] - 2026-05-15 <a class="header-anchor" href="#_1-0-0-2026-05-15" aria-label="Permalink to &quot;[1.0.0] - 2026-05-15&quot;">​</a></h2><h3 id="🚀-added-2" tabindex="-1">🚀 Added <a class="header-anchor" href="#🚀-added-2" aria-label="Permalink to &quot;🚀 Added&quot;">​</a></h3><ul><li><strong>Pydantic v2 support</strong>: Models can be used directly as database schemas.</li><li><strong>Django-like Query Syntax</strong>: Support for intuitive filtering such as <code>__gte</code>, <code>__in</code>, <code>__like</code>, etc.</li><li><strong>FTS5 Full-Text Search</strong>: Fast full-text search capabilities using SQLite&#39;s FTS5 extension.</li><li><strong>Automatic Index Management</strong>: B-tree indexes are automatically created using <code>Indexed[T]</code> and <code>UniqueIndexed[T]</code> annotations.</li><li><strong>Composite Indexes</strong>: Support for <code>CompositeIndex</code> via Pydantic&#39;s <code>Field</code> extra metadata.</li><li><strong>Transparent Type Handling</strong>: Automatically handles complex types like <code>dict</code> and <code>list</code> by serializing them to JSON.</li><li><strong>WAL Mode Support</strong>: Write-Ahead Logging is enabled by default for better performance and concurrency.</li><li><strong>Context Manager Support</strong>: <code>NyanSQLite</code> can be used as a context manager for automatic connection closing.</li></ul><h3 id="🔄-changed-2" tabindex="-1">🔄 Changed <a class="header-anchor" href="#🔄-changed-2" aria-label="Permalink to &quot;🔄 Changed&quot;">​</a></h3><ul><li>Initial public release of NyanSQLite.</li></ul><hr>',43)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
